import{z as A,x as m,o as l,c as p,q as r,j as e,D as i,d as s,s as t,S as o,b as n}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"min-plus 卷积","description":"","frontmatter":{"title":"min-plus 卷积","date":"2026-09-27T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/min-plus-conv.md","filePath":"cs/min-plus-conv.md","lastUpdated":1791413859000}'),B={name:"cs/min-plus-conv.md"};function d(g,a,u,f,D,c){const E=m("Mermaid");return l(),p("div",null,[a[2]||(a[2]=r('<h1 id="min-plus-卷积" tabindex="-1">min-plus 卷积 <a class="header-anchor" href="#min-plus-卷积" aria-label="Permalink to &quot;min-plus 卷积&quot;">​</a></h1><div class="epigraph"><p>把加法换成取 min、乘法换成加法，卷积就成了 DP 的合并动作——普通乘法有多快，决定了多少问题能成批解。</p><footer>—— 据 Bellman《Dynamic Programming》(1957)；(min,+) 代数与 SMAWK (1987)</footer></div><p><a href="/cs/matroid-theory">拟阵理论</a>划清了贪心的势力范围，本课换一块地基：<strong>代数</strong>。DP 转移「新值 = 上一段各处加代价后取最小」反复出现——背包合并、分段代价相加、字符串距离——它们全是同一个运算：\\((f\\star g)[k]=\\min_i(f[i]+g[k-i])\\)，即 <strong>min-plus 卷积</strong>。认出它，才知道哪些情形能快、哪些注定慢。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>朴素计算 \\(f\\star g\\) 要 \\(O(n^2)\\)。普通卷积靠 FFT 提速到 \\(O(n\\log n)\\)，但 FFT 依赖「乘法可分配、可逆」，min-plus 世界里这些都不成立。缺口：<strong>min-plus 卷积何时存在次平方算法</strong>。本课不碰一般情形的硬算——结论就是没有通用捷径，重点是认出可解特例。</p><p><span class="marginnote">术语翻译：(min,+) 代数（热带代数）= 把「加法」定义为 min、「乘法」定义为加法的半环；矩阵乘法照此定义搬过来，就是图上最短路的全源转移。</span></p><p><span class="marginnote">数字实例：\\(f=[0,2]\\)、\\(g=[1,0]\\)。\\((f\\star g)[0]=f[0]+g[0]=1\\)；\\((f\\star g)[1]=\\min(f[0]+g[1],f[1]+g[0])=\\min(0,3)=0\\)；\\((f\\star g)[2]=f[1]+g[1]=2\\)。结果 \\([1,0,2]\\)，长度 \\(n+m-1\\)，与普通卷积同构。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一般情形只有暴力双循环 \\(O(nm)\\)。可提速的两大特例：一是<strong>凹/凸序列</strong>——\\(f\\) 或 \\(g\\) 相邻差单调时，可证卷积结果也凸且最优断点单调，用 SMAWK 或分治决策单调把复杂度压到 \\(O(n)\\) 或 \\(O(n\\alpha(n))\\)；二是<strong>值域小</strong>——按值分桶后卷积可转成计数卷积再幂变换，视值域 \\(V\\) 得 \\(O(V\\log V)\\) 类做法。</p>',9)),(l(),e(o,null,{default:i(()=>[t(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%A6%81%E7%AE%97%20f%20%E2%8B%86%20g%22%5D%20--%3E%20B%7B%22f%20%E6%88%96%20g%20%E5%87%B8%3F%22%7D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20C%5B%22SMAWK%20%2F%20%E5%86%B3%E7%AD%96%E5%8D%95%E8%B0%83%20O(n)%22%5D%0A%20%20B%20--%3E%7C%22%E5%90%A6%22%7C%20D%7B%22%E5%80%BC%E5%9F%9F%E5%B0%8F%3F%22%7D%0A%20%20D%20--%3E%7C%22%E6%98%AF%22%7C%20E%5B%22%E5%88%86%E6%A1%B6%20%2B%20%E8%AE%A1%E6%95%B0%E5%8D%B7%E7%A7%AF%22%5D%0A%20%20D%20--%3E%7C%22%E5%90%A6%22%7C%20F%5B%22%E5%8F%8C%E5%BE%AA%E7%8E%AF%20O(nm)%22%5D%0A%20%20C%20--%3E%20G%5B%22%E5%BE%97%E5%88%B0%E7%BB%93%E6%9E%9C%22%5D%0A%20%20E%20--%3E%20G%0A%20%20F%20--%3E%20G%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,[n("span",{class:"marginnote"},"直觉类比：普通卷积像「两条河流在所有相位上叠加求和」；min-plus 卷积像「两个梯队会师，每个到达时刻只记最省的那条路线」。凸性相当于行军速度均匀——先到者恒先到，断点单调，不用回头比对。")],-1)),a[4]||(a[4]=n("h2",{id:"机制",tabindex:"-1"},[s("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=n("p",null,[s("为什么凸性能救命：若 \\(f\\) 凸，则 \\(f[i]+g[k-i]\\) 关于 \\(i\\) 的最优位置随 \\(k\\) 增大"),n("strong",null,"单调不降"),s("（决策单调性），一维最小化可由 SMAWK 对全行并行求出，每行只碰 \\(O(n)\\) 个候选。另一头的底层事实：把矩阵乘法定义成 (min,+) 乘，它与**全对最短路（APSP）**同难度；一维卷积可归约进矩阵乘，因此「通用的大幅次平方算法」缺乏理论依据——这也是「认出特例」如此重要的原因。")],-1)),(l(),e(o,null,{default:i(()=>[t(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%96%AD%E7%82%B9%E4%B8%BA%E4%BD%95%E5%8D%95%E8%B0%83%3F%22%5D%20--%3E%20R%5B%22f%20%E5%87%B8%3A%20%E5%A2%9E%E9%87%8F%20%CE%94f%20%E5%8D%95%E8%B0%83%E4%B8%8D%E9%99%8D%22%5D%0A%20%20R%20--%3E%20S%5B%22k%20%E5%8F%B3%E7%A7%BB%E4%B8%80%E6%AD%A5%2C%20%E6%9C%80%E4%BC%98%20i%20%E4%B8%8D%E5%B7%A6%E7%A7%BB%22%5D%0A%20%20S%20--%3E%20T%5B%22%E9%80%90%E8%A1%8C%E5%80%99%E9%80%89%E4%B8%8D%E9%87%8D%E5%8F%A0%20%E2%86%92%20%E7%BA%BF%E6%80%A7%22%5D%0A%20%20U%5B%22min-plus%20%E7%9F%A9%E9%98%B5%E4%B9%98%22%5D%20--%3E%7C%22%E5%BD%92%E7%BA%A6%22%7C%20V%5B%22%E5%85%A8%E5%AF%B9%E6%9C%80%E7%9F%AD%E8%B7%AF%20APSP%22%5D%0A%20%20V%20--%3E%7C%22%E7%96%91%E9%9A%BE%20%E2%86%92%20%E6%97%A0%E9%80%9A%E7%94%A8%E5%BF%AB%E7%AE%97%22%7C%20T%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">常见误区：见到 min-plus 就套 FFT——「用指数打分再取 min」只在代价可分解为独立和时成立；硬变换会引入耦合项。另一个误区是以为凸性可后验补救：序列不凸时 SMAWK 的单调前提已塌，输出会错，不是变慢。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>工程判定三问：转移是不是真 min-plus（有无耦合项）？序列是否凸或近似凸？值域是否受限？三个都否定，就老老实实 \\(O(n^2)\\) 并在常数上做文章。相邻关系：<a href="/cs/slope-trick">Slope Trick</a> 是凸 min-plus 卷积在「在线增量」下的堆式化身；SMAWK 与决策单调分治是同一单调性的两种批量实现；图上的 (min,+) 矩阵幂对应定长最短路，与 Floyd–Warshall 同源。</p><p><span class="marginnote">直觉类比：热带代数像把世界调成「只关心最好的一条路，其余通通当无穷大」；普通代数里万物求和，热带代数里万物竞争——竞争世界的乘法就是会师时的加价。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DP 合并的数学身份是 min-plus 卷积；通用次平方算法不存在（与 APSP 等价）。</li><li>凸性给决策单调，SMAWK/分治把它压到线性；值域小走分桶。</li><li>Slope Trick = 在线的凸 min-plus；先问凸不凸，再选工具。</li><li>出处：Bellman《Dynamic Programming》1957；Aggarwal–Park–SMAWK 1987；Chan–Williams APSP 归约 (2016)。</li></ul>',6))])}const F=A(B,[["render",d]]);export{C as __pageData,F as default};
